 put('tenochtitlan',['earlyMexico','earlyTribute'],[
  [1454,1480,L('Дань и расширение союза','Tribute and alliance expansion','Алым-салык жана союздун кеңейиши'),L('Тройственный союз подчиняет новые города в центральной Мексике и на побережье. Местные правители сохраняются, но отдают дань Теночтитлану, Тескоко и Тлакопану.','The Triple Alliance subjects more central Mexican and coastal towns. Local rulers remain but deliver tribute to Tenochtitlan, Texcoco and Tlacopan.','Үчтүк союз борбордук Мексикадагы жана жээктеги жаңы шаарларды баш ийдирет. Жергиликтүү башкаруучулар сакталып, Теночтитланга, Тескокого жана Тлакопанга алым төлөйт.'),[lake,morelos,gulf],'influence'],
  [1480,1521,L('Большая данническая держава','A large tributary empire','Ири алым-салык державасы'),L('К концу XV века даннические связи охватывают побережья и южные области. Тласкала и государство пурепеча сохраняют независимость. Провинции соединены дорогами, рынками и движением посольств.','By the late fifteenth century, tributary ties reach the coasts and southern regions. Tlaxcala and the Purépecha state remain independent. Roads, markets and embassies connect the provinces.','XV кылымдын аягында алым-салык байланыштары жээктерге жана түштүк аймактарга жетет. Тласкала менен пурепеча мамлекети көз карандысыз бойдон калат. Аймактарды жолдор, базарлар жана элчиликтер байланыштырат.'),[lake,morelos,gulf,oaxaca,soconusco],'influence',{learning:learn(L('Союз городов и зависимых правителей.','An alliance of cities and subject rulers.','Шаарлардын жана баш ийген башкаруучулардын союзу.'),L('Дань: ткани, продовольствие и ценные изделия.','Tribute includes cloth, food and valuable crafts.','Алымга кездеме, азык-түлүк жана баалуу буюмдар кирет.'),L('Общины сохраняют разные языки и местные традиции.','Communities retain distinct languages and local traditions.','Жамааттар өз тилдерин жана жергиликтүү салттарын сактайт.'))}]
 ]);
