 put('early-new-spain',['earlyMexico','earlyYucatan','earlyTribute'],[
  [1521,1535,L('Испанский центр в Мехико','A Spanish centre in Mexico City','Мехикодогу испан борбору'),L('Теночтитлан взят испанцами и многочисленными коренными союзниками. В Мехико складывается новый центр управления, распространяющий власть на покорённые центральные области.','Spaniards and numerous Indigenous allies capture Tenochtitlan. Mexico City becomes a new administrative centre extending authority over conquered central districts.','Испандар жана көп сандаган түпкү союздаштар Теночтитланды алат. Мехико басып алынган борбордук аймактарга бийлигин жайган жаңы башкаруу борборуна айланат.'),[mexicoCore],'polity'],
  [1535,1547,L('Вице-королевство Новая Испания','Viceroyalty of New Spain','Жаңы Испания вице-королдугу'),L('Вице-королевство учреждено в 1535 году. Города и зависимые общины образуют колониальную систему; северные походы и борьба за Юкатан продолжаются.','The viceroyalty is established in 1535. Towns and subject communities form a colonial system while northern campaigns and the struggle for Yucatán continue.','Вице-королдук 1535-жылы түзүлөт. Шаарлар жана баш ийген жамааттар колониялык тутумду түзөт; түндүктөгү жортуулдар жана Юкатан үчүн күрөш уланат.'),[mexicoCore,westMexico,oaxaca],'polity'],
  [1547,1601,L('Колониальные центры и фронтиры','Colonial centres and frontiers','Колониялык борборлор жана чек аймактар'),L('Городские, горнорудные и земледельческие районы расширяются. Эпидемии, принудительный труд и переселения тяжело затрагивают коренные общины, которые сохраняют местные институты и языки.','Urban, mining and farming districts expand. Epidemics, forced labour and resettlement gravely affect Indigenous communities, which retain local institutions and languages.','Шаарлар, кен жана дыйканчылык аймактары кеңейет. Эпидемиялар, мажбурланган эмгек жана көчүрүүлөр жергиликтүү мекемелерин жана тилдерин сактаган түпкү жамааттарга оор таасир тийгизет.'),[mexicoCore,westMexico,oaxaca,northYucatan],'polity',{learning:learn(L('Вице-король, городские советы и местные правители.','A viceroy, town councils and local rulers.','Вице-король, шаар кеңештери жана жергиликтүү башкаруучулар.'),L('Налоги, серебряные рудники и сельское хозяйство.','Tribute, silver mines and agriculture.','Салыктар, күмүш кендери жана айыл чарбасы.'),L('Коренные, европейские и африканские жители.','Indigenous, European and African inhabitants.','Түпкү, европалык жана африкалык тургундар.'))}]
 ],N('north','state',[-99.13,19.43],L('Новая Испания · основные области','New Spain · principal districts','Жаңы Испания · негизги аймактар'),'#b77b66'));

 put('taino',['earlyTaino','earlyCaribbean'],[
  [1454,1492,L('Островные общества и касики','Island societies and caciques','Аралдык коомдор жана касиктер'),L('Местные правители объединяют поселения Больших Антильских островов. Морские связи, земледелие и рыбная ловля обеспечивают жизнь общин.','Local rulers link settlements across the Greater Antilles. Seafaring, farming and fishing sustain communities.','Жергиликтүү башкаруучулар Чоң Антиль аралдарынын конуштарын бириктирет. Деңиз байланыштары, дыйканчылык жана балык уулоо жамааттарды камсыздайт.'),'previous','cultural'],
  [1492,1511,L('Контакты, сопротивление и колонизация','Contact, resistance and colonisation','Байланыш, каршылык жана колониялаштыруу'),L('Прибытие испанцев открывает эпоху вторжений и новых союзов. На Эспаньоле война и принудительная дань подрывают власть касиков; другие острова ещё сохраняют самостоятельные общества.','Spanish arrival begins an era of invasions and new alliances. War and forced tribute undermine Hispaniola’s caciques; other islands still retain independent societies.','Испандардын келиши баскынчылык жана жаңы союздар доорун ачат. Эспаньолада согуш менен мажбурланган алым касиктердин бийлигин алсыратат; башка аралдарда көз карандысыз коомдор сакталат.'),'previous','cultural'],
  [1511,1601,L('Коренная жизнь в колониальном Карибском регионе','Indigenous life in the colonial Caribbean','Колониялык Кариб аймагындагы түпкү элдердин жашоосу'),L('Завоевание, эпидемии и принудительный труд резко сокращают население. Выжившие жители сохраняют семьи, знания и элементы языка и культуры; история таино продолжается.','Conquest, epidemics and forced labour sharply reduce the population. Survivors preserve families, knowledge and elements of language and culture; Taíno history continues.','Басып алуу, эпидемиялар жана мажбурланган эмгек калктын санын кескин азайтат. Аман калгандар үй-бүлөлөрүн, билимин, тил жана маданият элементтерин сактайт; таино тарыхы уланат.'),'previous','cultural']
 ]);
