 put('cusco-inca',['earlyInca','earlyAndes'],[
  [1454,1470,L('Пачакути и центральные Анды','Pachacuti and the central Andes','Пачакути жана борбордук Анддар'),L('Власть Куско распространяется на высокогорные долины. Походы Пачакути и его сына сопровождаются строительством дорог, административных центров и хранилищ.','Cusco’s authority spreads through highland valleys. Pachacuti and his son accompany campaigns with roads, administrative centres and storehouses.','Кусконун бийлиги бийик тоолуу өрөөндөргө жайылат. Пачакути менен уулунун жортуулдары жолдорду, башкаруу борборлорун жана кампаларды куруу менен коштолот.'),[incaCore],'polity',{area:{name:incaNames}}],
  [1470,1480,L('Подчинение северного побережья','Subjugation of the northern coast','Түндүк жээкти баш ийдирүү'),L('Походы инков подчиняют Чиму и центральное побережье. При Тупаке Инке Юпанки владения расширяются, местные правители включаются в имперскую систему.','Inca campaigns subdue Chimú and the central coast. Under Tupac Inca Yupanqui the domains expand and local rulers enter the imperial system.','Инка жортуулдары Чимуну жана борбордук жээкти баш ийдирет. Тупак Инка Юпанкинин тушунда ээликтер кеңейип, жергиликтүү башкаруучулар империялык тутумга кирет.'),[inca1470],'polity',{area:{name:incaNames}}],
  [1480,1500,L('Походы Тупака и связь четырёх суйу','Tupac’s campaigns and the four suyus','Тупактын жортуулдары жана төрт суйунун байланышы'),L('Империя продвигается вдоль Анд на север и юг. Дороги соединяют разные природные области, а местные общины предоставляют государству труд и припасы.','The empire advances north and south along the Andes. Roads connect contrasting environments while local communities provide labour and supplies to the state.','Империя Анддарды бойлоп түндүккө жана түштүккө жылат. Жолдор ар башка жаратылыш аймактарын бириктирип, жергиликтүү жамааттар мамлекетке эмгек жана азык берет.'),[inca1480],'polity',{area:{name:incaNames}}],
  [1500,1527,L('Уайна-Капак и северные владения','Huayna Capac and the northern domains','Уайна-Капак жана түндүк ээликтер'),L('Уайна-Капак укрепляет власть в северных Андах и районе Кито. Империя достигает наибольшего распространения; покорённые народы сохраняют различия и местные элиты.','Huayna Capac consolidates the northern Andes and the Quito region. The empire reaches its greatest extent; subject peoples retain local elites and distinct identities.','Уайна-Капак түндүк Анддарда жана Кито аймагында бийлигин бекемдейт. Империя эң чоң көлөмүнө жетет; баш ийген элдер жергиликтүү элиталарын жана өзгөчөлүктөрүн сактайт.'),[inca1500],'polity',{area:{name:incaNames},learning:learn(L('Сапа Инка и местные кураки.','The Sapa Inca and local kurakas.','Сапа Инка жана жергиликтүү куракалар.'),L('Трудовая повинность, земледелие и государственные хранилища.','Labour obligations, farming and state storehouses.','Эмгек милдети, дыйканчылык жана мамлекеттик кампалар.'),L('Многоязычная империя; дороги и кипу связывают провинции.','A multilingual empire; roads and khipu connect provinces.','Көп тилдүү империя; жолдор жана кипу аймактарды байланыштырат.'))}],
  [1527,1532,L('Борьба Уаскара и Атауальпы','Conflict between Huascar and Atahualpa','Уаскар менен Атауальпанын күрөшү'),L('После смерти Уайна-Капака соперничество наследников перерастает в гражданскую войну. Армии Уаскара и Атауальпы борются за верховную власть.','After Huayna Capac’s death, rivalry among heirs becomes civil war. Huascar’s and Atahualpa’s armies contend for supreme power.','Уайна-Капак өлгөндөн кийин мураскорлордун атаандаштыгы ички согушка айланат. Уаскар менен Атауальпанын аскерлери жогорку бийлик үчүн күрөшөт.'),[inca1500],'influence',{area:{name:incaNames}}],
  [1532,1533,L('Пленение Атауальпы и кризис власти','Atahualpa’s capture and a crisis of power','Атауальпанын туткундалышы жана бийлик кризиси'),L('Испанский отряд пленяет Атауальпу в Кахамарке. Имперская власть распадается в условиях войны; испанцы ещё не контролируют всю территорию прежней державы.','A Spanish force captures Atahualpa at Cajamarca. Imperial authority fractures amid warfare; the Spanish do not yet control the former empire’s entire territory.','Испан отряды Кахамаркада Атауальпаны туткунга алат. Согуш шартында империялык бийлик ыдырайт; испандар мурдагы державанын бүт аймагын али көзөмөлдөбөйт.'),[inca1500],'influence',{area:{name:incaNames}}]
 ]);
 put('chimu',['earlyAndes'],[[1454,1470,L('Чиму перед инкским завоеванием','Chimú before Inca conquest','Инка басып алуусуна чейинки Чиму'),L('Чан-Чан управляет долинами северного побережья, включая Ламбайеке. Орошаемое земледелие и специализированное ремесло поддерживают державу.','Chan Chan governs northern coastal valleys, including Lambayeque. Irrigated farming and specialised crafts sustain the kingdom.','Чан-Чан Ламбайекени кошкондо түндүк жээктин өрөөндөрүн башкарат. Сугат дыйканчылыгы жана адистешкен кол өнөрчүлүк державаны камсыздайт.'),'previous','polity']]);
 put('early-chimu-communities',['earlyAndes','earlyInca'],[
  [1470,1533,L('Общины северного побережья под властью инков','North-coast communities under Inca rule','Инка бийлигиндеги түндүк жээк жамааттары'),L('После завоевания Чан-Чана верховная власть переходит к инкам. Часть мастеров переселяют в Куско; земледельческие и ремесленные общины продолжают жить в прибрежных долинах.','After Chan Chan’s conquest, supreme authority passes to the Inca. Some artisans are relocated to Cusco; farming and craft communities remain in coastal valleys.','Чан-Чан алынгандан кийин жогорку бийлик инкаларга өтөт. Айрым усталар Куского көчүрүлөт; дыйкан жана кол өнөрчү жамааттар жээк өрөөндөрүндө жашоосун улантат.'),[[[-79.6,-7.5],[-78.8,-7.5],[-78.2,-9.1],[-78.6,-9.3],[-79.3,-8.3]]],'cultural'],
  [1533,1601,L('Северное побережье в колониальную эпоху','The north coast in the colonial period','Колониялык доордогу түндүк жээк'),L('Испанские города, дань и новые земельные порядки преобразуют долины. Коренные земледельцы и мастера сохраняют местные знания и общинные связи.','Spanish towns, tribute and new land arrangements transform the valleys. Indigenous farmers and artisans preserve local knowledge and community ties.','Испан шаарлары, алым жана жаңы жер тартиби өрөөндөрдү өзгөртөт. Түпкү дыйкандар менен усталар жергиликтүү билимди жана жамааттык байланышты сактайт.'),'previous','cultural']
 ],N('south','community',[-79.07,-8.1],L('Северное побережье Перу','Peru’s north coast','Перунун түндүк жээги'),'#b79566'));
 put('sican',['lateTucume','earlyAndes'],[
  [1454,1470,L('Тукуме в державе Чиму','Túcume in the Chimú realm','Чиму державасындагы Тукуме'),L('Ламбайеке остаётся частью державы Чиму. В Тукуме местные правители управляют поселениями и обменом с побережьем.','Lambayeque remains part of the Chimú realm. Local lords at Túcume administer settlements and coastal exchange.','Ламбайеке Чиму державасынын курамында калат. Тукумеде жергиликтүү башкаруучулар конуштарды жана жээк алмашуусун башкарат.'),'previous','settlement'],
  [1470,1533,L('Ламбайеке в системе инков','Lambayeque in the Inca system','Инка тутумундагы Ламбайеке'),L('После падения Чиму инки используют местный административный центр. Прибрежное земледелие и ремесло продолжаются под новой верховной властью.','After Chimú falls, the Inca use the local administrative centre. Coastal farming and crafts continue under a new supreme authority.','Чиму кулагандан кийин инкалар жергиликтүү башкаруу борборун пайдаланат. Жээктеги дыйканчылык жана өнөр жаңы жогорку бийликте уланат.'),'previous','settlement'],
  [1533,1601,L('Ламбайекские общины после завоевания','Lambayeque communities after conquest','Басып алуудан кийинки Ламбайеке жамааттары'),L('Колониальный порядок меняет расселение и повинности. История населения Ламбайеке продолжается за пределами прежних монументальных центров.','Colonial rule alters settlement and labour obligations. Lambayeque’s population continues its history beyond the earlier monumental centres.','Колониялык тартип конуштарды жана эмгек милдеттерин өзгөртөт. Ламбайеке калкы мурдагы монументалдык борборлордон тышкары тарыхын улантат.'),[[[-80,-6.3],[-79.5,-6.3],[-79.45,-7.1],[-79.9,-7.1]]],'cultural']
 ]);
 put('chincha',['earlyAndes'],[[1454,1470,L('Чинча и прибрежный обмен','Chincha and coastal exchange','Чинча жана жээк алмашуусу'),L('Правители Чинчи контролируют богатую земледельческую долину. Местные торговцы связывают побережье и высокогорье.','Chincha’s rulers control a prosperous agricultural valley. Local traders link the coast and highlands.','Чинчанын башкаруучулары бай дыйканчылык өрөөнүн көзөмөлдөйт. Жергиликтүү соодагерлер жээкти жана бийик тоолорду байланыштырат.'),'previous','polity']]);
 put('early-chincha-valley',['earlyAndes','earlyInca'],[
  [1470,1533,L('Чинча под верховной властью инков','Chincha under Inca supremacy','Инкалардын үстөмдүгүндөгү Чинча'),L('Во второй половине XV века Чинча включается в державу инков. Местная элита и торговые связи сохраняют значение.','In the later fifteenth century Chincha enters the Inca empire. Its local elite and trading connections remain important.','XV кылымдын экинчи жарымында Чинча инка державасына кирет. Жергиликтүү элита жана соода байланыштары маанисин сактайт.'),[[[-76.5,-12.9],[-75.8,-12.7],[-75.3,-13.7],[-75.8,-14.1],[-76.4,-13.7]]],'cultural'],
  [1533,1601,L('Колониальная долина Чинча','Colonial Chincha Valley','Колониялык Чинча өрөөнү'),L('Испанское завоевание вводит новые налоги и земельные отношения. Местное население продолжает земледелие в долине, испытывая последствия эпидемий и принудительного труда.','Spanish conquest introduces new taxation and land relations. Local people continue valley agriculture amid epidemics and forced labour.','Испан басып алуусу жаңы салыктарды жана жер мамилелерин киргизет. Жергиликтүү калк эпидемиялар менен мажбурланган эмгектин таасиринде өрөөндө дыйканчылыкты улантат.'),'previous','cultural']
 ],N('south','community',[-76.17,-13.45],L('Общины долины Чинча','Chincha Valley communities','Чинча өрөөнүнүн жамааттары'),'#bd9972'));
 put('ichma',['earlyPachacamac'],[
  [1454,1470,L('Ичма и святилище Пачакамак','Ichma and the Pachacamac sanctuary','Ичма жана Пачакамак ыйык жайы'),L('Местные правители контролируют долины Лурина и Римака. Пачакамак привлекает паломников с побережья и из высокогорья.','Local rulers control the Lurín and Rímac valleys. Pachacamac attracts coastal and highland pilgrims.','Жергиликтүү башкаруучулар Лурин менен Римак өрөөндөрүн көзөмөлдөйт. Пачакамак жээктен жана бийик тоолордон зыяратчыларды тартат.'),'previous','polity'],
  [1470,1533,L('Инкское управление и храм Солнца','Inca administration and the Sun Temple','Инка башкаруусу жана Күн ибадатканасы'),L('Инки включают область в свою державу и перестраивают святилище. Местный курака управляет ресурсами долины под имперским верховенством.','The Inca incorporate the region and rebuild the sanctuary. A local kuraka manages valley resources under imperial supremacy.','Инкалар аймакты державасына кошуп, ыйык жайды кайра курат. Жергиликтүү курака империя үстөмдүгүндө өрөөндүн ресурстарын башкарат.'),'previous','cultural'],
  [1533,1601,L('Лурин после разграбления святилища','Lurín after the sanctuary is looted','Ыйык жай тонолгондон кийинки Лурин'),L('В 1533 году отряд Эрнандо Писарро разграбляет Пачакамак. Прежний религиозный центр утрачивает свою роль; поселения и земледельческие общины долины продолжают существовать.','In 1533 Hernando Pizarro’s force loots Pachacamac. The former religious centre loses its role; valley settlements and farming communities continue.','1533-жылы Эрнандо Писарронун отряды Пачакамакты тонойт. Мурдагы диний борбор ролун жоготот; өрөөндүн конуштары жана дыйкан жамааттары жашоосун улантат.'),'previous','cultural']
 ]);
 for(const [id,refs,incaText,colonialText] of [
  ['wanka',['wankaEducation','wankaSettlement','earlyInca'],L('Инкское управление перестраивает поселения Верхнего Мантаро и включает долину в систему дорог, хранилищ и трудовых повинностей.','Inca administration reorganises Upper Mantaro settlements and incorporates the valley into roads, storehouses and labour obligations.','Инка башкаруусу Жогорку Мантаронун конуштарын кайра түзүп, өрөөндү жолдор, кампалар жана эмгек милдеттери тутумуна кошот.'),L('После испанского вторжения местные правители договариваются с новой властью. Колониальное управление меняет налоги, но общины долины сохраняются.','After the Spanish invasion, local rulers negotiate with the new power. Colonial administration changes taxation, but valley communities endure.','Испан басып кирүүсүнөн кийин жергиликтүү башкаруучулар жаңы бийлик менен сүйлөшөт. Колониялык башкаруу салыкты өзгөртөт, бирок өрөөн жамааттары сакталат.')],
  ['lucre',['lucreEducation','earlyInca'],L('Долина Лукре входит в хозяйственный мир Куско. Прежняя самостоятельность Чокепукио сменяется инкским управлением землёй и трудом.','The Lucre basin belongs to Cusco’s economic hinterland. Chokepukio’s earlier autonomy gives way to Inca administration of land and labour.','Лукре өрөөнү Кусконун чарбалык аймагына кирет. Чокепукионун мурдагы өз алдынчалыгын жер менен эмгекти инкалык башкаруу алмаштырат.'),L('Колонизация меняет землевладение вокруг Куско. Долина остаётся обитаемой сельскохозяйственной областью; прежний центр не показан как независимое государство.','Colonisation changes landholding around Cusco. The basin remains an inhabited farming region; its former centre is not an independent polity.','Колониялаштыруу Кусконун айланасындагы жер ээлөөнү өзгөртөт. Өрөөн калк жашаган дыйканчылык аймагы бойдон калат; мурдагы борбор өз алдынча мамлекет эмес.')],
  ['aymara-lordships',['earlyInca','earlyAndes'],L('Инкские завоевания подчиняют владения вокруг Титикаки. Местные правители и аймарские общины участвуют в имперской системе земледелия, скотоводства и повинностей.','Inca conquests subdue the lordships around Titicaca. Local rulers and Aymara communities participate in imperial farming, herding and labour obligations.','Инка басып алуулары Титикаканын айланасындагы ээликтерди баш ийдирет. Жергиликтүү башкаруучулар менен аймара жамааттары империялык дыйканчылык, мал чарбасы жана эмгек милдеттерине катышат.'),L('Испанское управление опирается на местных правителей и вводит новые налоги. Аймарские общины продолжают земледелие и скотоводство; позднее возрастает трудовая повинность для рудников.','Spanish administration relies on local rulers and imposes new taxes. Aymara communities continue farming and herding; later, mining labour demands grow.','Испан башкаруусу жергиликтүү башкаруучуларга таянып, жаңы салыктарды киргизет. Аймара жамааттары дыйканчылык менен мал чарбасын улантат; кийин кендерге эмгек милдети көбөйөт.')]
 ])put(id,refs,[[1454,1533,L('Местные общества в державе инков','Local societies in the Inca empire','Инка державасындагы жергиликтүү коомдор'),incaText,'previous','cultural'],[1533,1601,L('Общины в условиях колонизации','Communities during colonisation','Колониялаштыруу шартындагы жамааттар'),colonialText,'previous','cultural']]);
 const vilcabamba=[[-73.6,-12.75],[-73,-12.55],[-72.5,-12.85],[-72.7,-13.35],[-73.35,-13.35]];
 put('early-vilcabamba',['earlyVilcabamba'],[
  [1537,1558,L('Манько Инка и его преемники','Manco Inca and his successors','Манько Инка жана анын мураскорлору'),L('После восстания у Куско инкский двор закрепляется в Вилькабамбе. Самостоятельное государство ведёт войну и переговоры с испанцами.','After the uprising at Cusco, the Inca court establishes itself in Vilcabamba. An independent state wages war and negotiates with the Spanish.','Кускодогу көтөрүлүштөн кийин инка сарайы Вилькабамбада бекемделет. Көз карандысыз мамлекет испандар менен согушуп, сүйлөшүүлөрдү жүргүзөт.'),[vilcabamba],'polity'],
  [1558,1572,L('Последний независимый инкский двор','The last independent Inca court','Акыркы көз карандысыз инка сарайы'),L('Титу Куси Юпанки, затем Тупак Амару сохраняют инкскую власть в горно-лесном регионе. Дипломатические контакты чередуются с вооружённым сопротивлением.','Titu Cusi Yupanqui and then Tupac Amaru maintain Inca authority in the forested mountains. Diplomatic contacts alternate with armed resistance.','Титу Куси Юпанки, андан соң Тупак Амару токойлуу тоолордо инка бийлигин сактайт. Дипломатиялык байланыштар куралдуу каршылык менен алмашат.'),[vilcabamba],'polity']
 ],N('south','state',[-73.24,-12.91],L('Инкское государство Вилькабамбы','Inca state of Vilcabamba','Вилькабамба инка мамлекети'),'#bf9d50'));
 const lima=[[-77.35,-11.65],[-76.65,-11.65],[-76.65,-12.45],[-77.35,-12.45]];
 const cusco=[[-72.4,-13.2],[-71.5,-13.2],[-71.5,-14],[-72.4,-14]];
 const colonialPeru=[[-80.2,-6],[-78.6,-5.8],[-76.8,-8.3],[-74.9,-10.8],[-73.9,-13.45],[-71.4,-14.2],[-70,-15.5],[-68.2,-16],[-66.4,-18.6],[-66.1,-21.1],[-67.9,-21.4],[-69.5,-18],[-71.5,-17],[-74.9,-14.4],[-77.3,-11.8],[-79.5,-8.5]];
 put('early-peru',['earlyAndes','earlyInca','earlyVilcabamba'],[
  [1533,1535,L('Захват Куско и местные союзы','Capture of Cusco and local alliances','Кусконун алынышы жана жергиликтүү союздар'),L('Испанцы и коренные союзники входят в Куско. Контроль над городами и дорогами остаётся спорным; правители и общины выбирают разные стратегии сопротивления и сотрудничества.','Spaniards and Indigenous allies enter Cusco. Control of towns and roads remains contested; rulers and communities pursue different strategies of resistance and cooperation.','Испандар жана түпкү союздаштар Куского кирет. Шаарлар менен жолдорду көзөмөлдөө талаштуу бойдон калат; башкаруучулар менен жамааттар каршылыктын жана кызматташуунун ар түрдүү жолдорун тандайт.'),[cusco],'settlement'],
  [1535,1542,L('Лима, Куско и войны за власть','Lima, Cusco and wars for power','Лима, Куско жана бийлик үчүн согуштар'),L('Основанная в 1535 году Лима становится прибрежным центром. Восстание Манько Инки и войны между конкистадорами препятствуют устойчивому контролю над Андами.','Lima, founded in 1535, becomes a coastal centre. Manco Inca’s uprising and wars among conquistadors obstruct stable control of the Andes.','1535-жылы негизделген Лима жээктеги борборго айланат. Манько Инканын көтөрүлүшү жана конкистадорлордун согуштары Анддарды туруктуу көзөмөлдөөгө тоскоол болот.'),[lima,cusco],'settlement'],
  [1542,1572,L('Вице-королевство Перу и независимая Вилькабамба','Viceroyalty of Peru and independent Vilcabamba','Перу вице-королдугу жана көз карандысыз Вилькабамба'),L('Учреждено вице-королевство Перу. Испанское управление распространяется из городов на населённые долины; Вилькабамба сохраняет самостоятельность, а Амазония остаётся вне этого ядра.','The Viceroyalty of Peru is created. Spanish administration extends from towns into populated valleys; Vilcabamba remains independent, while Amazonia lies outside this core.','Перу вице-королдугу түзүлөт. Испан башкаруусу шаарлардан калк жашаган өрөөндөргө жайылат; Вилькабамба көз карандысыздыгын сактап, Амазония бул өзөктөн тышкары калат.'),[colonialPeru,cusco],'polity'],
  [1572,1601,L('Колониальное управление и трудовые повинности','Colonial administration and labour obligations','Колониялык башкаруу жана эмгек милдеттери'),L('После захвата Вилькабамбы власть инкского двора прекращается. Реформы Толедо, переселение общин и горная мита усиливают колониальное извлечение труда и серебра.','After Vilcabamba’s capture, the independent Inca court ends. Toledo’s reforms, community resettlement and mining mita intensify colonial extraction of labour and silver.','Вилькабамба алынгандан кийин көз карандысыз инка сарайынын бийлиги аяктайт. Толедонун реформалары, жамааттарды көчүрүү жана кен митасы эмгек менен күмүштү колониялык пайдаланууну күчөтөт.'),[colonialPeru,cusco,vilcabamba],'polity']
 ],N('south','state',[-77.04,-12.05],L('Испанское Перу · основные области','Spanish Peru · principal districts','Испан Перусу · негизги аймактар'),'#bd8268'));
 put('muisca',['muisca','earlyMuisca'],[
  [1454,1537,L('Владения Боготы и Тунхи','The Bogotá and Tunja polities','Богота жана Тунха ээликтери'),L('Зипа, заке и другие правители соперничают на высокогорном плато. Земледелие, соль, ткани и золотые изделия связывают местные общины обменом.','The zipa, zaque and other rulers compete across the highland plateau. Farming, salt, cloth and goldwork link communities through exchange.','Зипа, заке жана башка башкаруучулар бийик тоолуу платодо атаандашат. Дыйканчылык, туз, кездеме жана алтын буюмдар жамааттарды алмашуу аркылуу байланыштырат.'),'previous','influence'],
  [1537,1539,L('Испанское вторжение на плато','Spanish invasion of the plateau','Испандардын платого басып кириши'),L('Экспедиция Хименеса де Кесады вторгается на плато и захватывает центры власти. В 1538 году объявлено испанское владение; местное сопротивление продолжается.','Jiménez de Quesada’s expedition invades the plateau and captures centres of power. Spanish possession is proclaimed in 1538; local resistance continues.','Хименес де Кесаданын экспедициясы платого кирип, бийлик борборлорун алат. 1538-жылы испан ээлиги жарыяланат; жергиликтүү каршылык уланат.'),'previous','cultural'],
  [1539,1601,L('Муиска в колониальном Новом Королевстве Гранада','Muisca in the colonial New Kingdom of Granada','Колониялык Жаңы Гранада падышалыгындагы муиска'),L('Новые города и энкомьенды меняют сбор дани и использование земли. Муиска сохраняют общины и местных руководителей в условиях испанского господства.','New towns and encomiendas change tribute and land use. Muisca communities and local leaders continue under Spanish domination.','Жаңы шаарлар жана энкомьендалар алым чогултууну, жер пайдаланууну өзгөртөт. Муиска испан үстөмдүгүндө жамааттарын жана жергиликтүү жетекчилерин сактайт.'),'previous','cultural']
 ]);
 put('early-new-granada',['earlyMuisca','earlyAndes'],[[1538,1601,L('Колониальные центры высокогорного плато','Colonial centres of the highland plateau','Бийик тоолуу платонун колониялык борборлору'),L('Санта-Фе и Тунха становятся центрами Нового Королевства Гранада. Испанские чиновники и владельцы энкомьенд подчиняют населённые долины; контроль не охватывает весь современный колумбийский материк.','Santa Fe and Tunja become centres of the New Kingdom of Granada. Spanish officials and encomenderos subjugate populated valleys; effective control does not cover all of modern Colombia.','Санта-Фе менен Тунха Жаңы Гранада падышалыгынын борборлоруна айланат. Испан кызматкерлери жана энкомьенда ээлери калктуу өрөөндөрдү баш ийдирет; иш жүзүндөгү көзөмөл азыркы Колумбиянын баарын камтыбайт.'),[[[-74.6,4.2],[-74.7,5.5],[-73.4,6],[-72.9,5.6],[-73.4,4.8],[-74,4.1]]],'polity']],N('south','state',[-74.08,4.6],L('Новое Королевство Гранада · ядро','New Kingdom of Granada · core','Жаңы Гранада падышалыгы · өзөк'),'#bd8268'));
 put('tairona',['earlyAndes','lateTairona'],[
  [1454,1525,L('Поселения Сьерра-Невады','Sierra Nevada settlements','Сьерра-Неваданын конуштары'),L('Террасы, каменные дороги и земледелие связывают горные центры тайрона. Местные правители участвуют в обмене между горами и Карибским побережьем.','Terraces, stone roads and farming link Tairona mountain centres. Local rulers participate in exchange between the mountains and Caribbean coast.','Террасалар, таш жолдор жана дыйканчылык тайронанын тоолуу борборлорун байланыштырат. Жергиликтүү башкаруучулар тоолор менен Кариб жээгинин ортосундагы алмашууга катышат.'),'previous','cultural'],
  [1525,1600,L('Сопротивление после основания Санта-Марты','Resistance after Santa Marta is founded','Санта-Марта негизделгенден кийинки каршылык'),L('Испанская Санта-Марта усиливает давление на соседние горные общества. Тайрона сопротивляются; их поселения не превращаются сразу в сплошную колониальную территорию.','Spanish Santa Marta increases pressure on neighbouring mountain societies. Tairona communities resist; their settlements do not immediately become a continuous colonial territory.','Испан Санта-Мартасы коңшу тоолуу коомдорго кысымды күчөтөт. Тайрона жамааттары каршылык көрсөтөт; алардын конуштары дароо туташ колониялык аймакка айланбайт.'),'previous','cultural'],
  [1600,1601,L('Подчинение и сохранение горных общин','Subjugation and survival of mountain communities','Баш ийдирүү жана тоолуу жамааттардын сакталышы'),L('В конце XVI века испанские кампании ломают власть ряда местных правителей. Горные общины и их культурная история продолжаются после завоевания.','At the end of the sixteenth century Spanish campaigns break the power of several local rulers. Mountain communities and their cultural history continue after conquest.','XVI кылымдын аягында испан жортуулдары бир катар жергиликтүү башкаруучулардын бийлигин сындырат. Тоолуу жамааттар жана алардын маданий тарыхы басып алуудан кийин уланат.'),'previous','cultural']
 ]);
 put('araucania',['vergel','earlyChile'],[
  [1454,1550,L('Южные земледельческие общества','Southern farming societies','Түштүктөгү дыйкан коомдору'),L('На юге Чили сохраняются самостоятельные земледельческие общины и местные союзы. Их история лежит за южной границей инкского господства.','Southern Chile retains independent farming communities and local alliances beyond the southern limit of Inca rule.','Чилинин түштүгүндө инка бийлигинин түштүк чегинен тышкары өз алдынча дыйкан жамааттары жана жергиликтүү союздар сакталат.'),'previous','cultural'],
  [1550,1598,L('Сопротивление мапуче испанским поселениям','Mapuche resistance to Spanish settlements','Мапучелердин испан конуштарына каршылыгы'),L('Основание испанских городов и попытки подчинить труд местных жителей вызывают длительную войну. Мапуче создают военные союзы и оспаривают колониальный контроль.','Spanish town foundations and attempts to command Indigenous labour lead to prolonged warfare. Mapuche groups form military alliances and contest colonial control.','Испан шаарларынын негизделиши жана түпкү тургундардын эмгегин баш ийдирүү аракети узак согушка алып келет. Мапуче топтору аскердик союздарды түзүп, колониялык көзөмөлгө каршы турат.'),'previous','cultural'],
  [1598,1601,L('Куралаба и отступление испанцев','Curalaba and Spanish retreat','Куралаба жана испандардын чегиниши'),L('Победа мапуче при Куралабе вызывает широкое восстание. Испанская сеть городов южнее Био-Био начинает разрушаться, укрепляя самостоятельность местных обществ.','The Mapuche victory at Curalaba sparks a widespread uprising. The Spanish urban network south of the Biobío begins to collapse, strengthening local autonomy.','Куралабадагы мапуче жеңиши кеңири көтөрүлүшкө түрткү берет. Био-Бионун түштүгүндөгү испан шаарлар тармагы кулай баштап, жергиликтүү өз алдынчалыкты бекемдейт.'),'previous','cultural',{area:{name:L('Мапуче · юг Чили','Mapuche · southern Chile','Мапуче · түштүк Чили')}}]
 ]);
 put('upper-xingu',['earlyXingu'],[[1454,1601,L('Поселения и управляемый амазонский ландшафт','Settlements and a managed Amazonian landscape','Конуштар жана адам башкарган Амазония ландшафты'),L('Дороги, площади, земляные сооружения и сельскохозяйственные участки соединяют поселения Верхнего Шингу. Эта обитаемая область остаётся вне португальских прибрежных колониальных центров XVI века.','Roads, plazas, earthworks and farming plots link Upper Xingu settlements. This inhabited region remains outside sixteenth-century Portuguese coastal colonial centres.','Жолдор, аянттар, топурак курулуштары жана айдоо жерлери Жогорку Шингунун конуштарын байланыштырат. Калк жашаган бул аймак XVI кылымдагы португал жээк колониялык борборлорунан тышкары калат.'),'previous','cultural',{learning:learn(L('Связанные местные общины и руководители.','Connected local communities and leaders.','Өз ара байланышкан жергиликтүү жамааттар жана жетекчилер.'),L('Земледелие, рыболовство и преобразование ландшафта.','Farming, fishing and landscape management.','Дыйканчылык, балык уулоо жана ландшафтты башкаруу.'),L('Поселения связаны дорогами и общими пространствами.','Roads and shared spaces connect settlements.','Жолдор жана жалпы мейкиндиктер конуштарды байланыштырат.'))}]]);
 const guanabaraNative=[[-43.9,-22.5],[-43.1,-22.2],[-42.3,-22.6],[-42.5,-23.05],[-43.8,-23.1]];
 put('early-tupinamba',['earlyGuanabara','earlyBrazil'],[
  [1454,1500,L('Прибрежные общества тупи','Coastal Tupi societies','Жээктеги тупи коомдору'),L('Поселения побережья соединяют земледелие, рыболовство и морские связи. Местные общины и союзы управляют своей жизнью до прибытия европейских флотов.','Coastal settlements combine farming, fishing and maritime connections. Local communities and alliances govern their own affairs before European fleets arrive.','Жээк конуштары дыйканчылыкты, балык уулоону жана деңиз байланыштарын айкалыштырат. Европалык флоттор келгенге чейин жергиликтүү жамааттар менен союздар өз турмушун башкарат.'),[guanabaraNative],'cultural'],
  [1500,1555,L('Торговля и соперничество на побережье','Trade and rivalry along the coast','Жээктеги соода жана атаандаштык'),L('Европейские купцы обменивают товары на бразильское дерево. Разные коренные группы заключают союзы с французами и португальцами и сопротивляются порабощению.','European traders exchange goods for brazilwood. Different Indigenous groups ally with French and Portuguese newcomers and resist enslavement.','Европалык соодагерлер товарларын бразил жыгачына алмашат. Түпкү элдердин ар башка топтору француздар жана португалдар менен союз түзүп, кулга айлантууга каршы турат.'),[guanabaraNative],'cultural'],
  [1555,1567,L('Тупинамба и французы в Гуанабаре','Tupinambá and French allies in Guanabara','Гуанабарадагы тупинамбалар жана француз союздаштары'),L('Тупинамба и связанные с ними группы поддерживают французское поселение. Против них выступают португальцы и их коренные союзники, включая темимино.','Tupinambá and associated groups support the French settlement. Portuguese forces and Indigenous allies, including the Temiminó, oppose them.','Тупинамба жана алар менен байланышкан топтор француз конушун колдойт. Аларга португал күчтөрү жана темиминону кошкондо түпкү союздаштар каршы чыгат.'),[guanabaraNative],'cultural'],
  [1567,1601,L('Общины после португальской победы','Communities after the Portuguese victory','Португал жеңишинен кийинки жамааттар'),L('Завоевание Гуанабары сопровождается перемещением жителей и ростом миссионерских поселений. Коренные общины продолжают существовать в колониальных центрах и за их пределами.','Guanabara’s conquest displaces inhabitants and expands mission settlements. Indigenous communities continue within and beyond colonial centres.','Гуанабаранын басып алынышы тургундардын жылышына жана миссионердик конуштардын көбөйүшүнө алып келет. Түпкү жамааттар колониялык борборлордо жана андан тышкары жашоосун улантат.'),[guanabaraNative],'cultural']
 ],N('south','community',[-43.1,-22.7],L('Тупинамба и общества Гуанабары','Tupinambá and Guanabara societies','Тупинамба жана Гуанабара коомдору'),'#699b74'));
 const saoVicente=[[-46.65,-24.1],[-46.65,-23.6],[-46.05,-23.6],[-46.05,-24.1]];
 const pernambuco=[[-35.35,-8.8],[-35.35,-7.45],[-34.7,-7.45],[-34.7,-8.8]];
